import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as s,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何在 RHEL 9 上配置 DHCP 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上配置 DHCP 服务器 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上配置 DHCP 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上配置 DHCP 服务器 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230425.0 ⭐️⭐️ How to Configure DHCP Server on RHEL 9  Rocky Linux 9","title":"如何在 RHEL 9 上配置 DHCP 服务器","tag":"202305","desc":""},"relativePath":"202305/20230425.0 ⭐️⭐️ How to Configure DHCP Server on RHEL 9  Rocky Linux 9.md","filePath":"[post].md"}'),c={name:"202305/20230425.0 ⭐️⭐️ How to Configure DHCP Server on RHEL 9  Rocky Linux 9.md"};function h(u,e,g,k,m,b){const i=p("Link");return o(),d("div",null,[e[15]||(e[15]=r(`<h1 id="如何在-rhel-9-上配置-dhcp-服务器" tabindex="-1">如何在 RHEL 9 上配置 DHCP 服务器 <a class="header-anchor" href="#如何在-rhel-9-上配置-dhcp-服务器" aria-label="Permalink to “如何在 RHEL 9 上配置 DHCP 服务器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/24/113729hi6cn36hicjgknjy.jpg" alt=""></p><p>DHCP 是 “<ruby>动态主机配置协议<rt>Dynamic Host Configuration Protocol</rt></ruby>” 的首字母缩写词，它是一种网络协议，可自动为计算机网络中的客户端系统分配 IP 地址。它从 DHCP 池或在其配置中指定的 IP 地址范围分配客户端。虽然你可以手动为客户端系统分配静态 IP，但 DHCP 服务器简化了这一过程，并为网络上的客户端系统动态分配 IP 地址。</p><p>在本文中，我们将演示如何在 RHEL 9 / Rocky Linux 9 上安装和配置 DHCP 服务器。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><ul><li>预装 RHEL 9 或 Rocky Linux 9</li><li>具有 sudo 管理权限的普通用户</li><li>本地配置的 YUM/DNF 仓库或 RHEL 9 的 Red Hat 订阅</li><li>互联网连接</li></ul><p>事不宜迟，让我们进入 DHCP 服务器安装步骤。</p><h3 id="_1、在-rhel-9-rocky-linux-9-上配置静态-ip-地址" tabindex="-1">1、在 RHEL 9 / Rocky Linux 9 上配置静态 IP 地址 <a class="header-anchor" href="#_1、在-rhel-9-rocky-linux-9-上配置静态-ip-地址" aria-label="Permalink to “1、在 RHEL 9 / Rocky Linux 9 上配置静态 IP 地址”">​</a></h3><p>开始时，必须在 RHEL 或 Rocky Linux 系统上设置静态 IP 地址。有多种方法可以执行此操作，但最简单和最直观的方法是使用 <code>nmtui</code> 或 <code>nmcli</code> 实用程序。</p><p>要确认你的 Linux 系统的 IP 地址，请运行以下 <code>ip</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Confirm-IP-Address-RHEL-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_2、安装和配置-dhcp-服务器" tabindex="-1">2、安装和配置 DHCP 服务器 <a class="header-anchor" href="#_2、安装和配置-dhcp-服务器" aria-label="Permalink to “2、安装和配置 DHCP 服务器”">​</a></h3><p>配置静态 IP 后，下一步就是安装 DHCP 服务器。RHEL 9 或 Rocky Linux 9 仓库 (BaseOS) 默认提供 <code>dhcp-server</code> 包，你可以如图所示安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install dhcp-server -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Install-DHCP-Server-DNF-Command.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>安装 dhcp 服务器后，我们需要进一步并配置设置。因此，打开 DHCP 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>将以下代码行粘贴到配置文件中。请务必将子网配置为你的首选值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>default-lease-time 3600;</span></span>
<span class="line"><span>max-lease-time 86400;</span></span>
<span class="line"><span>authoritative;</span></span>
<span class="line"><span>subnet 192.168.10.0 netmask 255.255.255.0 {</span></span>
<span class="line"><span>    range 192.168.10.100 192.168.10.200;</span></span>
<span class="line"><span>    option routers 192.168.10.1;</span></span>
<span class="line"><span>    option subnet-mask 255.255.255.0;</span></span>
<span class="line"><span>    option domain-name-servers 192.168.10.1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存并关闭文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/DHCP-Conf-File-RHEL-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>让我们看一下其中的一些值：</p><ul><li><code>default-lease-time</code> 值指定 DHCP 服务器将地址租给客户端的时间。在这种情况下，默认租用时间值为 3600 秒或 1 小时。</li><li><code>max-lease-time</code> 是将 IP 租给客户端的最长持续时间。在我们的例子中，这被设置为 86400 秒或 24 小时。</li><li>下一部分是子网配置。在此设置中，<code>192.168.10.0</code> 是子网，<code>255.255.255.0</code> 是子网掩码。IP 地址范围从 <code>192.168.10.100</code> 一直到 <code>192.168.10.200</code>。</li><li><code>router</code> 选项定义默认网关。在本例中为 <code>192.168.10.1</code>。</li><li><code>subnet-mask</code> 选项确定分配给每个客户端或主机的子网掩码。在本例中为 <code>255.255.255.0</code>。</li><li>最后，<code>domain-name-servers</code> 选项指定 DNS 服务器。在本例中为 <code>192.168.10.1</code>。</li></ul><p>完成后，保存更改并退出。然后启用并启动 DHCP 服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now dhcpd</span></span>
<span class="line"><span>$ sudo systemctl status dhcpd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/DHCP-Server-Service-Status-RHEL-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>请注意：</p><p>此时，DHCP 服务应该分发 IP 地址。如果你的 LAN 中有另一个 DHCP 服务器或路由器，关闭它以防止 IP 地址分配冲突是明智的。这将导致一些客户端从 RHEL 或 Rocky Linux 服务器上的 DHCP 服务器获得 IP 分配，而其余的则从路由器获得 IP 分配，这当然不是你想要发生的事情。因此，请记住关闭 LAN 设置中的任何其他 DHCP 服务器。</p><h3 id="_3、测试-dhcp-服务器安装" tabindex="-1">3、测试 DHCP 服务器安装 <a class="header-anchor" href="#_3、测试-dhcp-服务器安装" aria-label="Permalink to “3、测试 DHCP 服务器安装”">​</a></h3><p>在我们模拟的 LAN 设置中，你可以看到 Ubuntu 系统已经从 RHEL 或 Rocky Linux DHCP 服务器中选择了一个 IP。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Automatic-Assign-DHCP-Server-RHEL-RockyLinux-1024x584.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>回到我们的 DHCP 服务器并在 <code>/var/log/message</code> 文件中搜索 Ubuntu 机器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tail -50 /var/log/messages | grep -i 192.168.10.100</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/DHCP-Server-Logs-RHEL-RockyLinux-1024x116.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>完美，上面的输出确认 Ubuntu 机器从我们的 DHCP 服务器获得了 IP 服务器。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这篇文章到此结束。在本指南中，你学习了如何在 RHEL 9 / Rocky Linux 9 上安装和配置 DHCP 服务器。请在下面的评论部分发表你的疑问和反馈。</p><p>（题图：MJ/d396485d-963c-4d17-8c4b-f3c8e11dcc5d）</p><hr>`,40)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.linuxtechi.com/configure-dhcp-server-on-rhel-rockylinux/"},{default:n(()=>[...e[0]||(e[0]=[s("https://www.linuxtechi.com/configure-dhcp-server-on-rhel-rockylinux/",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),a(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...e[2]||(e[2]=[s("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(i,{href:"https://github.com/lkxed/"},{default:n(()=>[...e[3]||(e[3]=[s("lkxed",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const f=l(c,[["render",h]]);export{P as __pageData,f as default};
